/**
 * Query-time search plus the write-time index maintenance driven by `search.reindex_requested`.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, subscribe, isEnabled, consumeRateLimit
 */
import { subscribe } from "@/lib/event-bus";
import { isEnabled } from "@/lib/feature-flags";
import { assertCan } from "@/lib/permissions";
import { consumeRateLimit } from "@/lib/rate-limit";
import { assertOrgScope } from "@/lib/tenant";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import { orgResource } from "./_support";
import type { SearchQueryInput } from "@/schemas/search";
import type { SearchSubjectKind } from "@/server/repositories/search-repository";
import type { Comment } from "@/types/comment";
import type { OrgId, Page } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Issue } from "@/types/issue";
import type { Actor } from "@/types/member";
import type { Project } from "@/types/project";

export type SearchHit = {
  kind: SearchSubjectKind;
  id: string;
  title: string;
  snippet: string;
  href: string;
};

/** Characters of surrounding context kept on either side of a match. */
const SNIPPET_RADIUS = 60;

/** Token bucket protecting the index from query bursts. */
const SEARCH_QUERY_BUCKET = "search:query";

/**
 * Runs a query against the denormalised index. Field-scoped syntax
 * (`status:done`) is an `advanced_search` feature, so a query containing a
 * colon is rejected for plans that do not include it rather than silently
 * being treated as literal text.
 */
export async function search(
  actor: Actor,
  input: SearchQueryInput,
): Promise<Page<SearchHit>> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "issue:read", orgResource(input.orgId));

  const verdict = await consumeRateLimit(input.orgId, SEARCH_QUERY_BUCKET);
  if (!verdict.allowed) {
    throw new Error(
      `Search rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  const org = await orgRepo.findOrgById(input.orgId);
  const advanced = isEnabled("advanced_search", {
    orgId: input.orgId,
    userId: actor.userId,
    plan: org?.plan ?? "free",
    role: actor.role,
    overrides: org?.settings.enabledFlagOverrides,
  });

  if (input.q.includes(":") && !advanced) {
    throw new Error("Field-scoped search is not included in this plan");
  }

  const page = await searchRepo.searchDocuments(input);

  return {
    items: page.items.map((row) => ({
      kind: row.subjectKind,
      id: row.subjectId,
      title: row.content.split("\n")[0] ?? row.subjectId,
      snippet: snippetAround(row.content, input.q),
      href: hrefFor(row.subjectKind, row.subjectId),
    })),
    nextCursor: page.nextCursor,
    total: page.total,
  };
}

export async function indexIssue(orgId: OrgId, issue: Issue): Promise<void> {
  await searchRepo.upsertSearchDocument(
    orgId,
    "issue",
    issue.id,
    [issue.title, issue.description ?? ""].join("\n"),
    issue.projectId,
  );
}

export async function indexComment(
  orgId: OrgId,
  comment: Comment,
): Promise<void> {
  await searchRepo.upsertSearchDocument(
    orgId,
    "comment",
    comment.id,
    comment.body,
    null,
  );
}

export async function indexProject(
  orgId: OrgId,
  project: Project,
): Promise<void> {
  await searchRepo.upsertSearchDocument(
    orgId,
    "project",
    project.id,
    [project.name, project.description ?? ""].join("\n"),
    project.id,
  );
}

export async function removeFromIndex(
  orgId: OrgId,
  subjectKind: SearchSubjectKind,
  subjectId: string,
): Promise<void> {
  await searchRepo.deleteSearchDocument(orgId, subjectKind, subjectId);
}

/**
 * Keeps the index in step with writes. Every handler re-reads the row rather
 * than trusting the event payload, so a partially-applied write can never be
 * indexed as if it had succeeded.
 */
export function registerSearchListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    subscribe("issue.created", async (payload) => {
      const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
      if (issue) await indexIssue(payload.orgId, issue);
    }),
    subscribe("issue.updated", async (payload) => {
      const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
      if (issue) await indexIssue(payload.orgId, issue);
    }),
    subscribe("issue.archived", async (payload) => {
      await removeFromIndex(payload.orgId, "issue", payload.issueId);
    }),
    subscribe("comment.created", async (payload) => {
      const comment = await commentRepo.findCommentById(
        payload.orgId,
        payload.commentId,
      );
      if (comment) await indexComment(payload.orgId, comment);
    }),
    subscribe("comment.deleted", async (payload) => {
      await removeFromIndex(payload.orgId, "issue", payload.commentId);
    }),
    subscribe("project.created", async (payload) => {
      const project = await projectRepo.findProjectById(
        payload.orgId,
        payload.projectId,
      );
      if (project) await indexProject(payload.orgId, project);
    }),
    subscribe("project.archived", async (payload) => {
      await removeFromIndex(payload.orgId, "project", payload.projectId);
    }),
    subscribe("search.reindex_requested", async (payload) => {
      if (payload.subjectKind !== "issue") return;
      const issue = await issueRepo.findIssueById(
        payload.orgId,
        payload.subjectId as Issue["id"],
      );
      if (issue) await indexIssue(payload.orgId, issue);
    }),
  ];

  return () => {
    for (const off of offs) off();
  };
}

function hrefFor(kind: SearchSubjectKind, subjectId: string): string {
  switch (kind) {
    case "issue":
      return `/issues/${subjectId}`;
    case "comment":
      return `/comments/${subjectId}`;
    case "project":
      return `/projects/${subjectId}`;
  }
}

function snippetAround(content: string, query: string): string {
  const at = content.toLowerCase().indexOf(query.toLowerCase());
  if (at < 0) return content.slice(0, SNIPPET_RADIUS * 2);

  const start = Math.max(0, at - SNIPPET_RADIUS);
  const end = Math.min(content.length, at + query.length + SNIPPET_RADIUS);
  return `${start > 0 ? "…" : ""}${content.slice(start, end)}${
    end < content.length ? "…" : ""
  }`;
}
/**
 * Denormalised search index kept in step by `SearchService`.
 */
import { and, count, desc, eq, inArray, like } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, searchIndex } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { compact, keysetPredicate, probeLimit, toPage } from "./_paging";
import type { SearchQueryInput } from "@/schemas/search";
import type { SearchIndexRow } from "@/server/db/schema/webhooks";
import type { OrgId, Page, ProjectId } from "@/types/common";

/**
 * Upsert by (org, kind, subject) rather than by row id: the indexer is called
 * on every write and must be idempotent.
 */
export async function upsertSearchDocument(
  orgId: OrgId,
  subjectKind: SearchSubjectKind,
  subjectId: string,
  content: string,
  projectId: ProjectId | null,
): Promise<void> {
  const db = getDb();
  const indexedAt = toIsoTimestamp(new Date());

  const existing = db
    .select({ id: searchIndex.id })
    .from(searchIndex)
    .where(
      and(
        orgPredicate(searchIndex.orgId, orgId),
        eq(searchIndex.subjectKind, subjectKind),
        eq(searchIndex.subjectId, subjectId),
      ),
    )
    .get();

  if (existing) {
    db.update(searchIndex)
      .set({ content, projectId, indexedAt })
      .where(eq(searchIndex.id, existing.id))
      .run();
    return;
  }

  db.insert(searchIndex)
    .values({
      id: newId(),
      orgId,
      subjectKind,
      subjectId,
      projectId,
      content,
      indexedAt,
    })
    .run();
}

export async function deleteSearchDocument(
  orgId: OrgId,
  subjectKind: SearchSubjectKind,
  subjectId: string,
): Promise<void> {
  getDb()
    .delete(searchIndex)
    .where(
      and(
        orgPredicate(searchIndex.orgId, orgId),
        eq(searchIndex.subjectKind, subjectKind),
        eq(searchIndex.subjectId, subjectId),
      ),
    )
    .run();
}

/**
 * Substring match over the denormalised content column. Deliberately simple —
 * the index is a convenience layer, not a search engine, and the tenant filter
 * is what actually matters here.
 */
export async function searchDocuments(
  input: SearchQueryInput,
): Promise<Page<SearchIndexRow>> {
  const db = getDb();
  const sort = { sortColumn: searchIndex.indexedAt, idColumn: searchIndex.id };

  const filters = compact(
    orgPredicate(searchIndex.orgId, input.orgId),
    like(searchIndex.content, `%${input.q}%`),
    input.kinds.length === 0
      ? undefined
      : inArray(searchIndex.subjectKind, [...input.kinds]),
    input.projectId === undefined
      ? undefined
      : eq(searchIndex.projectId, input.projectId),
  );

  const total = db
    .select({ value: count() })
    .from(searchIndex)
    .where(and(...filters))
    .get();

  const rows = db
    .select()
    .from(searchIndex)
    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))
    .orderBy(desc(searchIndex.indexedAt), desc(searchIndex.id))
    .limit(probeLimit(input.limit))
    .all();

  return toPage(
    rows,
    input.limit,
    total?.value ?? 0,
    (row) => row,
    (row) => ({ id: row.id, sortValue: row.indexedAt }),
  );
}

/** Drift alarm input: how many documents this org currently has indexed. */
export async function countIndexed(orgId: OrgId): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(searchIndex)
    .where(orgPredicate(searchIndex.orgId, orgId))
    .get();
  return row?.value ?? 0;
}

export type SearchSubjectKind = 'issue' | 'comment' | 'project';
/**
 * Rebuilds the search index for one organization; used after a bulk import or an index drift alarm.
 *
 * Must call (do not reimplement): indexIssue, indexComment, indexProject
 */
import { createLogger } from "@/lib/logger";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import {
  indexComment,
  indexIssue,
  indexProject,
} from "@/server/services/search-service";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { OrgId } from "@/types/common";

/** Rows read per page while walking the org's content. */
const PAGE_SIZE = 100;

const logger = createLogger("search-reindex-job");

/**
 * Walks one tenant's live projects, issues and comments and re-upserts every
 * document. Scoped to a single org on purpose: a full-fleet reindex is a
 * sequence of these, so one slow tenant cannot stall the rest.
 */
export async function runSearchReindexJob(orgId: OrgId): Promise<JobResult> {
  return runJob("search-reindex", async (result) => {
    const projects = await projectRepo.listProjects({
      orgId,
      limit: PAGE_SIZE,
      cursor: null,
    });

    for (const project of projects.items) {
      try {
        await indexProject(orgId, project);
        result.processed += 1;
      } catch (error) {
        result.failed += 1;
        logger.error("failed to index project", {
          projectId: project.id,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }

    // Archived issues are still readable from their permalink, so the
    // rebuild covers them as well; the thread walk below picks up every
    // comment in reading order, replies included, in a single query.
    const issues = await issueRepo.listIssues({
      orgId,
      limit: PAGE_SIZE,
      cursor: null,
      includeArchived: true,
    });

    for (const issue of issues.items) {
      try {
        await indexIssue(orgId, issue);
        result.processed += 1;

        const thread = await commentRepo.listThread(orgId, issue.id);
        const comments = thread.flatMap((node) => [
          node.comment,
          ...node.replies,
        ]);

        for (const comment of comments) {
          await indexComment(orgId, comment);
          result.processed += 1;
        }
      } catch (error) {
        result.failed += 1;
        logger.error("failed to index issue", {
          issueId: issue.id,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}
/**
 * Comment creation, edit window enforcement, mention extraction and soft delete.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, archivePatch, consumeRateLimit
 */
import { emit } from "@/lib/event-bus";
import { resolveMentions } from "@/lib/mentions";
import { assertCan } from "@/lib/permissions";
import { consumeRateLimit } from "@/lib/rate-limit";
import { archivePatch, assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import {
  actorEnvelope,
  commentResource,
  issueResource,
  requireFound,
} from "./_support";
import type {
  CreateCommentInput,
  DeleteCommentInput,
  UpdateCommentInput,
} from "@/schemas/comment";
import type { Comment, CommentThreadNode } from "@/types/comment";
import type { IssueId, OrgId, UserId } from "@/types/common";
import type { Actor } from "@/types/member";

/** How long after posting an author may still edit their own comment. */
const EDIT_WINDOW_MS = 15 * 60 * 1000;

/** How many members are scanned when resolving `@handle` mentions. */
const MENTION_LOOKUP_LIMIT = 100;

/** Token bucket protecting the comment thread from burst posting. */
const COMMENT_CREATE_BUCKET = "comment:create";

/**
 * Posts a comment on a live issue. Mentions written as `@handle` in the body
 * are resolved against the org's members here, so the stored row and the
 * `comment.created` payload agree on who was mentioned — the notification
 * fan-out reads that list rather than re-parsing the markdown.
 */
export async function createComment(
  actor: Actor,
  input: CreateCommentInput,
): Promise<Comment> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "comment:create", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);

  const verdict = await consumeRateLimit(input.orgId, COMMENT_CREATE_BUCKET);
  if (!verdict.allowed) {
    throw new Error(
      `Comment rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  const mentionedUserIds = await resolveMentionedUsers(
    input.orgId,
    input.body,
    input.mentionedUserIds,
  );

  const comment = await commentRepo.insertComment(
    { ...input, mentionedUserIds: [...mentionedUserIds] },
    actor.userId,
  );

  await emit("comment.created", {
    ...actorEnvelope(actor),
    commentId: comment.id,
    issueId: comment.issueId,
    mentionedUserIds,
  });

  return comment;
}

/**
 * Edits are allowed inside a fifteen-minute window, or by anyone the role
 * matrix already lets update a comment. `can()` decides the second half —
 * this service only owns the time window.
 */
export async function updateComment(
  actor: Actor,
  input: UpdateCommentInput,
): Promise<Comment> {
  assertOrgScope(actor, input.orgId);

  const comment = requireFound(
    await commentRepo.findCommentById(input.orgId, input.commentId),
    "Comment",
    input.commentId,
  );
  assertCan(actor, "comment:update", commentResource(comment));
  assertNotArchived("Comment", comment.id, comment);

  if (comment.authorId === actor.userId && isPastEditWindow(comment)) {
    throw new Error("The edit window for this comment has closed");
  }

  return commentRepo.updateComment(input);
}

/**
 * Deletion is soft: the row keeps its place so replies below it still have an
 * anchor. `archivePatch()` is what the repository writes; asking for it here
 * documents that this service deliberately never issues a hard delete.
 */
export async function deleteComment(
  actor: Actor,
  input: DeleteCommentInput,
): Promise<Comment> {
  assertOrgScope(actor, input.orgId);

  const comment = requireFound(
    await commentRepo.findCommentById(input.orgId, input.commentId),
    "Comment",
    input.commentId,
  );
  assertCan(actor, "comment:delete", commentResource(comment));
  assertNotArchived("Comment", comment.id, comment);

  const { archivedAt } = archivePatch();
  const archived = await commentRepo.archiveComment(
    input.orgId,
    input.commentId,
  );

  await emit("comment.deleted", {
    ...actorEnvelope(actor),
    occurredAt: archivedAt,
    commentId: archived.id,
    issueId: archived.issueId,
  });

  return archived;
}

export async function getThread(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly CommentThreadNode[]> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "comment:read", issueResource(issue));

  return commentRepo.listThread(orgId, issueId);
}

function isPastEditWindow(comment: Comment): boolean {
  const posted = new Date(comment.createdAt).getTime();
  return Date.now() - posted > EDIT_WINDOW_MS;
}

/**
 * Union of the ids the client already resolved (optimistic UI) and the ones
 * parsed out of the body server-side. The server list wins on disagreement.
 */
async function resolveMentionedUsers(
  orgId: OrgId,
  body: string,
  clientProvided: readonly UserId[],
): Promise<readonly UserId[]> {
  const members = await memberRepo.listMembers({
    orgId,
    limit: MENTION_LOOKUP_LIMIT,
    cursor: null,
  });

  const resolved = resolveMentions(body, members.items);
  const known = new Set(members.items.map((member) => member.userId));

  return [
    ...new Set([...resolved, ...clientProvided.filter((id) => known.has(id))]),
  ];
}
/**
 * Comment rows, soft deleted so a deleted comment keeps its place in the thread.
 *
 * Must call (do not reimplement): archivePatch, shouldFilterArchived
 */
import { and, asc, count, desc, eq, isNull } from "drizzle-orm";
import { newId } from "@/lib/id";
import { archivePatch, shouldFilterArchived } from "@/lib/soft-delete";
import { comments, getDb, users } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { compact, keysetPredicate, probeLimit, toPage } from "./_paging";
import { toComment, toUser } from "./_mappers";
import type {
  CreateCommentInput,
  ListCommentsInput,
  UpdateCommentInput,
} from "@/schemas/comment";
import type {
  Comment,
  CommentThreadNode,
  CommentWithAuthor,
} from "@/types/comment";
import type { CommentId, IssueId, OrgId, Page, UserId } from "@/types/common";

export async function findCommentById(
  orgId: OrgId,
  commentId: CommentId,
): Promise<Comment | null> {
  const row = getDb()
    .select()
    .from(comments)
    .where(and(orgPredicate(comments.orgId, orgId), eq(comments.id, commentId)))
    .get();
  return row ? toComment(row) : null;
}

export async function listComments(
  input: ListCommentsInput,
): Promise<Page<CommentWithAuthor>> {
  const db = getDb();
  const sort = { sortColumn: comments.createdAt, idColumn: comments.id };

  const filters = compact(
    orgPredicate(comments.orgId, input.orgId),
    eq(comments.issueId, input.issueId),
    shouldFilterArchived(input) ? isNull(comments.archivedAt) : undefined,
  );

  const total = db
    .select({ value: count() })
    .from(comments)
    .where(and(...filters))
    .get();

  const rows = db
    .select({ comment: comments, author: users })
    .from(comments)
    .innerJoin(users, eq(users.id, comments.authorId))
    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))
    .orderBy(desc(comments.createdAt), desc(comments.id))
    .limit(probeLimit(input.limit))
    .all();

  return toPage(
    rows,
    input.limit,
    total?.value ?? 0,
    (row) => ({ ...toComment(row.comment), author: toUser(row.author) }),
    (row) => ({ id: row.comment.id, sortValue: row.comment.createdAt }),
  );
}

/**
 * The whole thread for one issue, in reading order: top-level comments oldest
 * first, each followed by its replies. Archived comments are kept so a reply
 * chain never loses its anchor — the UI renders them as "deleted".
 */
export async function listThread(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly CommentThreadNode[]> {
  const rows = getDb()
    .select({ comment: comments, author: users })
    .from(comments)
    .innerJoin(users, eq(users.id, comments.authorId))
    .where(
      and(
        orgPredicate(comments.orgId, orgId),
        eq(comments.issueId, issueId),
      ),
    )
    .orderBy(asc(comments.createdAt))
    .all();

  const decorated: CommentWithAuthor[] = rows.map((row) => ({
    ...toComment(row.comment),
    author: toUser(row.author),
  }));

  const repliesBy = new Map<string, CommentWithAuthor[]>();
  for (const comment of decorated) {
    if (comment.parentId === null) continue;
    const bucket = repliesBy.get(comment.parentId) ?? [];
    bucket.push(comment);
    repliesBy.set(comment.parentId, bucket);
  }

  return decorated
    .filter((comment) => comment.parentId === null)
    .map((comment) => ({
      comment,
      replies: repliesBy.get(comment.id) ?? [],
    }));
}

export async function countComments(
  orgId: OrgId,
  issueId: IssueId,
): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(comments)
    .where(
      and(
        orgPredicate(comments.orgId, orgId),
        eq(comments.issueId, issueId),
      ),
    )
    .get();
  return row?.value ?? 0;
}

export async function insertComment(
  input: CreateCommentInput,
  authorId: UserId,
): Promise<Comment> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(comments)
    .values({
      id: newId(),
      orgId: input.orgId,
      issueId: input.issueId,
      authorId,
      body: input.body,
      parentId: input.parentId,
      editedAt: null,
      mentionedUserIds: JSON.stringify(input.mentionedUserIds),
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toComment(row);
}

/** An edit stamps `edited_at`, which the UI shows next to the timestamp. */
export async function updateComment(
  input: UpdateCommentInput,
): Promise<Comment> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .update(comments)
    .set({ body: input.body, editedAt: stamp, updatedAt: stamp })
    .where(
      and(
        orgPredicate(comments.orgId, input.orgId),
        eq(comments.id, input.commentId),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Comment ${input.commentId} not found`);
  return toComment(row);
}

export async function archiveComment(
  orgId: OrgId,
  commentId: CommentId,
): Promise<Comment> {
  const row = getDb()
    .update(comments)
    .set(archivePatch())
    .where(and(orgPredicate(comments.orgId, orgId), eq(comments.id, commentId)))
    .returning()
    .get();

  if (!row) throw new Error(`Comment ${commentId} not found`);
  return toComment(row);
}

