/**
 * Rebuilds the search index for one organization; used after a bulk import or an index drift alarm.
 *
 * Must call (do not reimplement): indexIssue, indexComment, indexProject
 */
import { createLogger } from "@/lib/logger";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import {
  indexComment,
  indexIssue,
  indexProject,
  removeFromIndex,
} from "@/server/services/search-service";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { OrgId, Page } from "@/types/common";

/** Rows read per page while walking the org's content. */
const PAGE_SIZE = 100;

const logger = createLogger("search-reindex-job");

/** Walks a keyset-paginated listing to the end, one page at a time. */
async function* walkPages<T>(
  fetchPage: (cursor: string | null) => Promise<Page<T>>,
): AsyncGenerator<T> {
  let cursor: string | null = null;
  do {
    const page: Page<T> = await fetchPage(cursor);
    yield* page.items;
    cursor = page.nextCursor;
  } while (cursor !== null);
}

function subjectKey(kind: searchRepo.SearchSubjectKind, id: string): string {
  return `${kind}:${id}`;
}

/**
 * Walks one tenant's live projects, issues and comments and re-upserts every
 * document, then drops any document that no longer belongs to live content
 * (deleted comments, archived issues and their comments, archived projects).
 * Scoped to a single org on purpose: a full-fleet reindex is a sequence of
 * these, so one slow tenant cannot stall the rest.
 */
export async function runSearchReindexJob(orgId: OrgId): Promise<JobResult> {
  return runJob("search-reindex", async (result) => {
    const live = new Set<string>();

    for await (const project of walkPages((cursor) =>
      projectRepo.listProjects({ orgId, limit: PAGE_SIZE, cursor }),
    )) {
      live.add(subjectKey("project", project.id));
      try {
        await indexProject(orgId, project);
        result.processed += 1;
      } catch (error) {
        result.failed += 1;
        logger.error("failed to index project", {
          projectId: project.id,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }

    // Only live issues are indexed; archived ones (and their comments) are
    // pruned below. Every non-deleted comment is indexed, including a live
    // reply whose parent was deleted.
    for await (const issue of walkPages((cursor) =>
      issueRepo.listIssues({ orgId, limit: PAGE_SIZE, cursor }),
    )) {
      live.add(subjectKey("issue", issue.id));
      try {
        await indexIssue(orgId, issue);
        result.processed += 1;

        for await (const comment of walkPages((cursor) =>
          commentRepo.listComments({
            orgId,
            issueId: issue.id,
            includeArchived: false,
            limit: PAGE_SIZE,
            cursor,
          }),
        )) {
          live.add(subjectKey("comment", comment.id));
          await indexComment(orgId, comment);
          result.processed += 1;
        }
      } catch (error) {
        result.failed += 1;
        logger.error("failed to index issue", {
          issueId: issue.id,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }

    for (const doc of await searchRepo.listIndexedSubjects(orgId)) {
      if (live.has(subjectKey(doc.subjectKind, doc.subjectId))) continue;
      await removeFromIndex(orgId, doc.subjectKind, doc.subjectId);
    }
  });
}
